import { callTool } from './tools/nats_bridge.ts';
const target={{ json .target }};
const response=await callTool("recipe--application_data_v1",{operation:"read",namespace:"cib-accompagnement",record_key:target.id});
const payload=response&&response.data?response.data:response;
if(!payload||!payload.record||typeof payload.record!=="object") throw new Error("broker_record_invalid");
const item=payload.record;
if(item.namespace!=="cib-accompagnement"||item.key!==target.id) throw new Error("broker_record_identity_invalid");
if(!Number.isSafeInteger(item.revision)||item.revision<0) throw new Error("broker_revision_invalid");
if(!item.data||typeof item.data!=="object") throw new Error("broker_record_data_invalid");
const permissions=item.permissions;
if(!permissions||typeof permissions.can_read!=="boolean"||typeof permissions.can_write!=="boolean"||typeof permissions.can_manage!=="boolean") throw new Error("broker_permissions_invalid");
const shares=Array.isArray(item.shares)?item.shares:[];const permissions_summary="Lecture : "+(permissions.can_read===true?"oui":"non")+" · Modification : "+(permissions.can_write===true?"oui":"non")+" · Partage : "+(permissions.can_manage===true?"oui":"non");const share_count=shares.length;
const d=item.data;
return {record:d,content:JSON.stringify(d,null,2),revision:item.revision,owner_user_id:typeof item.owner_user_id==="string"?item.owner_user_id:"",permissions,permissions_summary,shares,share_count,effects:[{type:"open_form",payload:{form_id:"save-dossier",submit_event:"save",prefill:{dossier_id:d.id,entreprise:d.entreprise,objectif:d.objectif,resultat_observe:d.resultat_observe,preuve_ref:d.preuve_ref,blocage:d.blocage,prochaine_etape:d.prochaine_etape,confirmation_manuelle:"non"}}},{type:"open_form",payload:{form_id:"accompagnement-share",submit_event:"share",prefill:{share_dossier_id:item.key,share_expected_revision:String(item.revision),share_subject_user_id:"",share_permission:"read",share_confirmation_manuelle:"non"}}}]};
